@@ -0,0 +1,29 @@
+// Sites (kitchens). Every location belongs to one site; a batch belongs to
+// the site of its location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Ids of the locations at a site. */
+export function siteLocationIds(store, site = DEFAULT_SITE) {
+  return new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+}
+
+/** True when `location` is a location of `site`. */
+export function locationInSite(store, location, site = DEFAULT_SITE) {
+  return store.data.locations.some((l) => l.id === location && l.site === site);
+}
+
+/** The batches at a site (all items), in store order. */
+export function siteBatches(store, site = DEFAULT_SITE) {
+  const ids = siteLocationIds(store, site);
+  return store.data.batches.filter((b) => ids.has(b.location));
+}
