@@ -0,0 +1,112 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { migrate } from "../src/db/migrations.js";
+import { memoryStore } from "../src/db/store.js";
+import { createOrder, receiveOrder, sendOrder } from "../src/domain/orders.js";
+import { app, fresh, seed } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+const at = "2026-10-28T09:00:00Z";
+
+// The seed with one batch of butter (item 3) received into the annex fridge.
+function withAnnexButter() {
+  const store = fresh();
+  const order = createOrder(store, { supplierId: 2, lines: [{ itemId: 3, qty: 2 }] }, { today: "2026-10-28" });
+  sendOrder(store, order.id);
+  const [batch] = receiveOrder(store, order.id, [{ lot: "AN-1", expires: "2026-10-30", location: "annex-fridge" }], { at, site: "annex" });
+  return { store, batch };
+}
+
+test("schema 2 files open as schema 3 with every location at main", () => {
+  const v2 = JSON.parse(readFileSync(new URL("../data/db.json", import.meta.url), "utf8"));
+  v2.schemaVersion = 2;
+  delete v2.sites;
+  v2.locations = v2.locations.filter((l) => l.id !== "annex-fridge").map(({ site, ...l }) => l);
+  const data = migrate(v2);
+  assert.equal(data.schemaVersion, 3);
+  assert.deepEqual(data.sites.map((s) => s.id), ["main"]);
+  assert.ok(data.locations.every((l) => l.site === "main"));
+  assert.deepEqual(data.batches, v2.batches);
+});
+
+test("the seed has the annex site and its fridge", () => {
+  const data = seed();
+  assert.deepEqual(data.sites.find((s) => s.id === "annex"), { id: "annex", name: "Annex kitchen" });
+  assert.deepEqual(data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+  assert.equal(memoryStore(data).data.schemaVersion, 3);
+});
+
+test("an unknown site is a 400 with its own code; no header means main", async () => {
+  const { handle } = app();
+  const bad = await handle({ path: "/items", headers: { "X-Larder-Site": "attic" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /attic/);
+  const lower = await handle({ path: "/items", headers: { "x-larder-site": "main" } });
+  assert.equal(lower.body.find((i) => i.id === 1).onHand, 10);
+});
+
+test("batches and stock on hand only show the request's site", async () => {
+  const { store, batch } = withAnnexButter();
+  const { handle } = app(store);
+  const annexItems = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(annexItems.length, store.data.items.length);
+  assert.equal(annexItems.find((i) => i.id === 3).onHand, 2);
+  assert.equal(annexItems.find((i) => i.id === 1).onHand, 0);
+  assert.equal((await handle({ path: "/items/3" })).body.onHand, 1.5);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batch.id]);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batch.id));
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: "/batches/6", headers: ANNEX })).status, 404);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { store, batch } = withAnnexButter();
+  const { handle } = app(store);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(store.data.batches.find((b) => b.id === batch.id).qty, 2);
+});
+
+test("alerts and stock value only count the request's site", async () => {
+  const { store } = withAnnexButter();
+  const { handle } = app(store);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AN-1"]);
+  assert.ok(alerts.lowStock.some((i) => i.name === "onion"));
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 2 * 945);
+  const main = (await handle({ path: "/alerts" })).body;
+  assert.ok(!main.expiring.some((b) => b.lot === "AN-1"));
+});
+
+test("orders are received into a location of the request's site", async () => {
+  const { handle } = app();
+  const res = await handle({ method: "POST", path: "/orders/2/receive", body: { lots: [{ lot: "a", expires: null, location: "annex-fridge" }, { lot: "b", expires: null, location: "fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { store, batch } = withAnnexButter();
+  const { handle } = app(store);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: 6, counted: 1 } })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: batch.id, counted: 1.5 } });
+  const res = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.deepEqual(res.body.lines, [{ batchId: batch.id, expected: 2, counted: 1.5, diff: -0.5 }]);
+});
+
+test("the nightly job checks every site", () => {
+  const { store } = withAnnexButter();
+  const { handle } = app(store);
+  return handle({ method: "POST", path: "/jobs/nightly" }).then(() => {
+    const keys = store.data.outbox.map((m) => m.key);
+    assert.ok(!keys.includes("low:2026-10-28"));
+    assert.ok(keys.includes("low:annex:2026-10-28"));
+    assert.ok(store.data.outbox.some((m) => m.subject.includes("AN-1") && m.subject.includes("Annex kitchen")));
+  });
+});
